// Masks the host BEFORE anything is stored or rendered. Real host is kept
// in-memory only on this item (raw_host) for the dedupe + schema-gate steps
// downstream in THIS SAME execution; only host_ref (a stable hash) and the
// already-public business_name/niche/city signals ever reach Postgres.
// Handles both input shapes: the GitHub sample file ({leads:[...]}) and a
// Postgres read of ep09_leads (rows already flat).
function djb2(str) {
  var s = String(str || '');
  var hash = 5381;
  for (var i = 0; i < s.length; i++) {
    hash = ((hash * 33) ^ s.charCodeAt(i)) >>> 0;
  }
  return hash.toString(16);
}

function hostFrom(raw) {
  var s = String(raw || '').trim().toLowerCase();
  s = s.replace(/^[a-z][a-z0-9+.-]*:\/\//, '');
  s = s.split('/')[0].split('?')[0].split('#')[0];
  s = s.split('@').pop().split(':')[0];
  s = s.replace(/^www\./, '');
  return s;
}

var rows = [];
for (var i = 0; i < $input.all().length; i++) {
  var j = $input.all()[i].json;
  if (Array.isArray(j.leads)) {
    rows = rows.concat(j.leads);
  } else if (Array.isArray(j.rows)) {
    rows = rows.concat(j.rows);
  } else if (j.host || j.website) {
    rows.push(j);
  }
}

var out = [];
for (var k = 0; k < rows.length; k++) {
  var r = rows[k];
  var rawHost = hostFrom(r.host || r.website || '');
  if (!rawHost) continue;
  out.push({ json: {
    lead_id: r.lead_id || null,
    host_ref: 'h_' + djb2(rawHost),
    raw_host: rawHost,
    business_name: r.business_name || null,
    niche: r.niche || null,
    city: r.city || null,
    signal: r.signal || null,
    source: r.source || null
  } });
}

if (out.length === 0) {
  throw new Error('Mask + normalize: zero lead rows after normalize -- refusing to run the draft lane on no data.');
}

return out;

// Dedupe by HOST, not place/row (memory feedback-outreach-dedupe-by-host-not-place):
// a chain sold on 4 branches is one inbox. Keeps the FIRST occurrence per raw_host
// within this batch; every later row with the same host is dropped and counted.
var seen = {};
var out = [];
var droppedHosts = [];

for (var i = 0; i < $input.all().length; i++) {
  var item = $input.all()[i];
  var host = String(item.json.raw_host || '').toLowerCase();
  if (!host) continue;
  if (seen[host]) {
    droppedHosts.push(host);
    continue;
  }
  seen[host] = true;
  out.push(item);
}

// stash the drop count on every surviving item so Run summary can report it
// without a second lookup pass.
for (var k = 0; k < out.length; k++) {
  out[k].json._dedupe_in = $input.all().length;
  out[k].json._dedupe_dropped = droppedHosts.length;
}

return out;

// Enforces the daily/run caps from ep09_caps BEFORE any LLM call. Throws (hard
// stop, same shape as EP06's write whitelist) rather than silently truncating --
// a silent truncation would be a honeypot fake-OK (memory
// feedback-honeypot-silent-accept-is-a-fake-success).
var caps = {};
try {
  caps = $('Load caps').first().json || {};
} catch (e) {
  caps = {};
}

if (caps.kill_enabled === false) {
  throw new Error('Guard: cap -- kill_enabled is false. Refusing to draft (human-disarmed).');
}
if (caps.breaker_tripped === true) {
  throw new Error('Guard: cap -- breaker_tripped is true. Refusing to draft until reset.');
}

var maxPerRun = Number(caps.max_drafts_per_run || 5);
var maxPerDay = Number(caps.max_drafts_per_day || 50);
var llmPerDay = Number(caps.llm_calls_per_day || 50);
var callsToday = Number(caps.llm_calls_today || 0);

var items = $input.all();
if (items.length > maxPerRun) {
  items = items.slice(0, maxPerRun);
}

var remaining = llmPerDay - callsToday;
if (remaining <= 0) {
  throw new Error('Guard: cap -- llm_calls_today (' + callsToday + ') has reached llm_calls_per_day (' + llmPerDay + '). Refusing to call the model.');
}
if (items.length > remaining) {
  items = items.slice(0, remaining);
}

if (items.length === 0) {
  throw new Error('Guard: cap -- zero leads survive the cap gate (max_drafts_per_run=' + maxPerRun + ', llm budget remaining=' + remaining + ').');
}

return items;

// Builds the per-lead prompt text for the Draft chain. Kept as its own node so
// the chainLlm prompt expression stays a single field reference, not an inline
// template -- easier to unit-test the string in isolation.
var out = [];
for (var i = 0; i < $input.all().length; i++) {
  var j = $input.all()[i].json;
  var signal = j.signal || 'no specific signal captured for this lead';
  var niche = j.niche || 'unspecified industry';
  var city = j.city || 'unspecified location';
  var name = j.business_name || 'the business';

  var prompt = 'Write ONE short outreach draft message for a cold lead. ' +
    'Business: ' + name + '. Industry: ' + niche + '. Location: ' + city + '. ' +
    'The one real signal we have about them: ' + signal + '. ' +
    'Rules: reference the signal above (or say plainly that no signal was found, never invent one). ' +
    'No hype, no superlatives, no price talk, no made-up URLs or links. ' +
    'Maximum 120 words. Plain, direct, one paragraph. ' +
    'Return ONLY raw JSON, no markdown fences, no extra text, matching exactly this shape: ' +
    '{"draft": "the message text", "confidence": 0.0, "reason": "one-line reason for that confidence score"}.';

  out.push({ json: Object.assign({}, j, { prompt_text: prompt }) });
}
return out;

// Schema gate. Runs per item. Enforces: stage from confidence, rejects any URL
// in the draft that is not the lead's own raw_host, rejects >120 words. Throws
// (never silently drops) -- REFUTE-FIRST requirement: prove this actually
// blocks a foreign URL and an over-length draft, not just accepts everything.
function wordCount(s) {
  var t = String(s || '').trim();
  if (!t) return 0;
  return t.split(/\s+/).length;
}

function urlsIn(s) {
  var t = String(s || '');
  var matches = t.match(/(https?:\/\/[^\s)]+|\bwww\.[^\s)]+|\b[a-z0-9-]+\.(com|net|org|io|co|ai|example)\b)/gi);
  return matches || [];
}

function hostOf(u) {
  var s = String(u || '').toLowerCase();
  s = s.replace(/^[a-z][a-z0-9+.-]*:\/\//, '');
  s = s.split('/')[0].split('?')[0].split('#')[0];
  s = s.replace(/^www\./, '');
  return s;
}

// chainLlm's own output ({text:"..."}) does NOT carry the input item's other
// fields through (unlike a Code node's Object.assign passthrough) -- host_ref
// and raw_host must be pulled from the paired upstream item by node reference,
// matched on item index [observed 2026-09-24, exec 34588: idempotency_key was
// "ep09:undefined:..." on every row until this fix].
var draftJson = $json;
var lead = {};
try {
  lead = $('Build prompt').item.json || {};
} catch (e) {
  lead = {};
}

var parsed = draftJson.output || draftJson.text || draftJson;
if (typeof parsed === 'string') {
  try { parsed = JSON.parse(parsed); } catch (e) { parsed = { draft: parsed, confidence: 0, reason: 'unparsed model output' }; }
}

var draft = String((parsed && parsed.draft) || '');
var confidence = Number((parsed && parsed.confidence) != null ? parsed.confidence : 0);
var reason = String((parsed && parsed.reason) || '');
var allowedHost = String(lead.raw_host || '').toLowerCase();
var hostRef = lead.host_ref || null;

var wc = wordCount(draft);
if (wc > 120) {
  throw new Error('SCHEMA GATE: draft is ' + wc + ' words, over the 120-word limit. host_ref=' + hostRef);
}

var found = urlsIn(draft);
for (var i = 0; i < found.length; i++) {
  var h = hostOf(found[i]);
  if (h && h !== allowedHost) {
    throw new Error('SCHEMA GATE: draft contains a URL (' + found[i] + ') not present in the lead row. host_ref=' + hostRef);
  }
}

var stage = confidence >= 0.7 ? 'draft-ready' : 'needs-review';

return { json: {
  host_ref: hostRef,
  stage: stage,
  draft: draft,
  confidence: confidence,
  reason: reason,
  word_count: wc,
  idempotency_key: 'ep09:' + hostRef + ':' + $now.toFormat('yyyyLLdd')
} };

var callsToday = 0;
try { callsToday = Number($('Load caps').first().json.llm_calls_today || 0); } catch (e) { callsToday = 0; }
return [{ json: { new_llm_calls_today: callsToday + $input.all().length } }];

// One summary item read straight off the execution panel.
function all(name) {
  try { return $(name).all().map(function (i) { return i.json; }); } catch (e) { return []; }
}

var normalized = all('Mask + normalize');
var deduped = all('Dedupe by host');
var gated = all('Guard: cap');
var drafted = all('Schema gate');
var rejected = all('Rejected (schema gate)');
var written = all('Write draft');

// Schema gate's output includes BOTH accepted items (have `stage`) and
// continueRegularOutput error-wrapper items (no `stage`, routed to
// Rejected (schema gate) by Valid draft?) -- only count the accepted ones here.
var draftReady = 0, needsReview = 0;
for (var i = 0; i < drafted.length; i++) {
  if (!drafted[i] || !drafted[i].stage) continue;
  if (drafted[i].stage === 'draft-ready') draftReady++;
  else needsReview++;
}

var dedupeIn = deduped.length ? Number(deduped[0]._dedupe_in || deduped.length) : 0;
var dedupeDropped = deduped.length ? Number(deduped[0]._dedupe_dropped || 0) : 0;

return [{ json: {
  leads_in: normalized.length,
  after_dedupe: deduped.length,
  dedupe_dropped: dedupeDropped,
  drafts_attempted: gated.length,
  drafts_rejected_by_schema_gate: rejected.length,
  drafts_written: written.length,
  stage_draft_ready: draftReady,
  stage_needs_review: needsReview,
  llm_calls_this_run: gated.length
} }];
